  "Something went wrong while fetching your data. Try again, or go back to your dashboard.": { kn: "ನಿಮ್ಮ ಡೇಟಾ ತರುವಾಗ ಏನೋ ತಪ್ಪಾಯಿತು. ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ ಅಥವಾ ನಿಮ್ಮ ಡ್ಯಾಶ್‌ಬೋರ್ಡ್‌ಗೆ ಹಿಂತಿರುಗಿ.", hi: "आपका डेटा लाते समय कुछ गलत हो गया। दोबारा कोशिश करें या अपने डैशबोर्ड पर वापस जाएं।" },
  "Try again": { kn: "ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ", hi: "फिर से कोशिश करें" },
