  "Show password": { kn: "ಪಾಸ್‌ವರ್ಡ್ ತೋರಿಸಿ", hi: "पासवर्ड दिखाएं" },
  "Hide password": { kn: "ಪಾಸ್‌ವರ್ಡ್ ಮರೆಮಾಡಿ", hi: "पासवर्ड छिपाएं" },
  // ── Phase 1: marketing chrome ──
  "SproutBox home": { kn: "SproutBox ಮುಖಪುಟ", hi: "SproutBox होम" },
