  "No registration number has been submitted.": { kn: "ಯಾವುದೇ ನೋಂದಣಿ ಸಂಖ್ಯೆಯನ್ನು ಸಲ್ಲಿಸಿಲ್ಲ.", hi: "कोई पंजीकरण नंबर जमा नहीं किया गया।" },
