  "Filter orders": { kn: "ಆರ್ಡರ್‌ಗಳನ್ನು ಫಿಲ್ಟರ್ ಮಾಡಿ", hi: "ऑर्डर फ़िल्टर करें" },
  "Search orders": { kn: "ಆರ್ಡರ್‌ಗಳನ್ನು ಹುಡುಕಿ", hi: "ऑर्डर खोजें" },
