  "grown": { kn: "ಬೆಳೆದಿದೆ", hi: "उगा" },
  "No check-ins yet. Your photos will be listed here after your first check-in.": { kn: "ಇನ್ನೂ ಚೆಕ್-ಇನ್‌ಗಳಿಲ್ಲ. ನಿಮ್ಮ ಮೊದಲ ಚೆಕ್-ಇನ್ ನಂತರ ಫೋಟೋಗಳು ಇಲ್ಲಿ ಪಟ್ಟಿಯಾಗುತ್ತವೆ.", hi: "अभी कोई चेक-इन नहीं। पहले चेक-इन के बाद आपकी फोटो यहां सूचीबद्ध होंगी।" },
  "No reason was recorded. Ask the team for details.": { kn: "ಯಾವುದೇ ಕಾರಣವನ್ನು ದಾಖಲಿಸಿಲ್ಲ. ವಿವರಗಳಿಗಾಗಿ ತಂಡವನ್ನು ಕೇಳಿ.", hi: "कोई कारण दर्ज नहीं हुआ। विवरण के लिए टीम से पूछें।" },
  "My tasks": { kn: "ನನ್ನ ಕೆಲಸಗಳು", hi: "मेरे काम" },
  "Filter tasks": { kn: "ಕೆಲಸಗಳನ್ನು ಫಿಲ್ಟರ್ ಮಾಡಿ", hi: "काम फ़िल्टर करें" },
  "Your growing tasks will be listed here.": { kn: "ನಿಮ್ಮ ಬೆಳೆಸುವ ಕೆಲಸಗಳು ಇಲ್ಲಿ ಪಟ್ಟಿಯಾಗುತ್ತವೆ.", hi: "आपके उगाने के काम यहां सूचीबद्ध होंगे।" },
  "Every task is up to date.": { kn: "ಎಲ್ಲಾ ಕೆಲಸಗಳು ನವೀಕೃತವಾಗಿವೆ.", hi: "सभी काम अद्यतन हैं।" },
  "New growing tasks appear here when the team assigns them to you.": { kn: "ತಂಡವು ಹೊಸ ಬೆಳೆಸುವ ಕೆಲಸಗಳನ್ನು ನಿಮಗೆ ನೀಡಿದಾಗ ಇಲ್ಲಿ ಕಾಣಿಸುತ್ತವೆ.", hi: "टीम के नए काम सौंपने पर वे यहां दिखेंगे।" },
  "Nothing waiting for pickup": { kn: "ಪಿಕಪ್‌ಗೆ ಯಾವುದೂ ಕಾಯುತ್ತಿಲ್ಲ", hi: "पिकअप के लिए कुछ इंतज़ार में नहीं" },
  "When a tray is ready, request a pickup and it will be listed here.": { kn: "ಟ್ರೇ ಸಿದ್ಧವಾದಾಗ ಪಿಕಪ್‌ಗೆ ವಿನಂತಿಸಿ, ಅದು ಇಲ್ಲಿ ಪಟ್ಟಿಯಾಗುತ್ತದೆ.", hi: "ट्रे तैयार होने पर पिकअप का अनुरोध करें, वह यहां सूचीबद्ध होगा।" },
  "No completed tasks yet": { kn: "ಇನ್ನೂ ಪೂರ್ಣಗೊಂಡ ಕೆಲಸಗಳಿಲ್ಲ", hi: "अभी कोई पूरा काम नहीं" },
  "Harvested and cancelled tasks are kept here.": { kn: "ಕೊಯ್ಲು ಮಾಡಿದ ಮತ್ತು ರದ್ದಾದ ಕೆಲಸಗಳನ್ನು ಇಲ್ಲಿ ಇಡಲಾಗುತ್ತದೆ.", hi: "कटाई हो चुके और रद्द किए गए काम यहां रखे जाते हैं।" },
  "Back to active tasks": { kn: "ಸಕ್ರಿಯ ಕೆಲಸಗಳಿಗೆ ಹಿಂತಿರುಗಿ", hi: "सक्रिय कामों पर वापस जाएं" },
  "New growing tasks will appear here when the team assigns them to you.": { kn: "ತಂಡವು ಹೊಸ ಬೆಳೆಸುವ ಕೆಲಸಗಳನ್ನು ನಿಮಗೆ ನೀಡಿದಾಗ ಇಲ್ಲಿ ಕಾಣಿಸುತ್ತವೆ.", hi: "टीम के नए काम सौंपने पर वे यहां दिखेंगे।" },
  "Active trays": { kn: "ಸಕ್ರಿಯ ಟ್ರೇಗಳು", hi: "सक्रिय ट्रे" },
