      const day = weekday ? WEEKDAY_NAMES[language][WEEKDAYS.indexOf(weekday as (typeof WEEKDAYS)[number])] : "";
      return language === "kn"
        ? `${n} ಆರ್ಡರ್‌ಗಳು ದಾರಿಯಲ್ಲಿವೆ.${day ? ` ಮುಂದಿನ ವಿತರಣೆ ${day}.` : ""}`
        : `${n} ऑर्डर रास्ते में हैं।${day ? ` अगली डिलीवरी ${day}।` : ""}`;
